steps.script:
function transform(ctx) {
  var u = ctx.vars.portal_url || "";
  if (!u || u.indexOf("?") < 0) throw new Error("未能获取门户跳转地址，请核对本校门户地址后把地址写进本步骤脚本");
  var q = u.slice(u.indexOf("?") + 1);
  var host = u.split("/")[2];
  // 原 cbi suselogin.lua L23-26 的 isp 选项 value（预编码中文）：宜宾电信/宜宾移动/校园网/宜宾联通
  var MAP = { "校园网": "校园网", "电信": "宜宾电信", "移动": "宜宾移动", "联通": "宜宾联通" };
  var isp = (ctx.isp || "").trim();
  var service = isp ? (MAP[isp] !== undefined ? MAP[isp] : isp) : "校园网";
  return { portal_host: host, qse: q.replace(/&/g, "%2526").replace(/=/g, "%253D"), eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), es: url_encode(service) };
}
